mapper.select:
SELECT pp.unity_no, pp.product_part_sign, pp.model, SUM(COALESCE(iod.accrual_await_qualified, 0)) AS accrual_await_qualified, SUM(COALESCE(iod.in_qualified, 0) + COALESCE(iod.in_un_qualified, 0)) AS neededInStorageNum, SUM(COALESCE(iod.accrual_await_qualified, 0)) - (SUM(COALESCE(iod.in_qualified, 0)) + SUM(COALESCE(iod.in_un_qualified, 0))) AS difference FROM ${inboundOrderDetailTableName} iod LEFT JOIN ${productPartTableName} pp ON iod.product_or_part = pp.primary_key WHERE iod.state != #{state} and iod.enterprise_code = #{enterpriseCode} and iod.delete_flag = false
AND iod.create_time >= #{requestData.startTime}
AND iod.create_time <= #{requestData.endTime}
GROUP BY pp.unity_no, pp.product_part_sign, pp.model order by difference desc
